'use client';

import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import { useRaf } from '@/hooks/use-raf';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { useResizeObserver } from '@/hooks/use-resize-observer';
import { useSmoothPointer } from '@/hooks/use-smooth-pointer';
import { useVisibility } from '@/hooks/use-visibility';
import { hasWebGL, loseContext, pixelRatio } from '@/lib/webgl';
import {
  BAYER8_DITHER_FRAG,
  BAYER8_DITHER_VERT,
} from '@/components/motion/shaders/bayer8-ordered-dither';

/* ==========================================================================
   Bit-Math Bayer8 Ordered Dither
   --------------------------------------------------------------------------
   Raw WebGL2. A smooth gradient is reduced to a handful of levels through an
   8x8 ordered-dither matrix that is DERIVED from gl_FragCoord with six integer
   ops — no lookup texture, no 64-float uniform array, no branches. The full
   derivation lives at the top of the shader file.

   Uploading a 8x8 texture would mean a second texture unit, a sampler, a
   GL_NEAREST filter that some drivers still get wrong on non-power-of-two
   viewports, and a resource to dispose. Six integer instructions cost less
   than the texture fetch they replace.
   ========================================================================== */

export interface Bayer8OrderedDitherProps {
  /** Output steps per channel, both ends included. 2 is pure 1-bit. */
  levels?: number;
  /** CSS pixels per dither cell. Scaled by DPR so the texture is stable. */
  cellSize?: number;
  /** Multiplier on the sweep. */
  speed?: number;
  /** Darkest output colour, linear 0..1 RGB. */
  dark?: readonly [number, number, number];
  /** Lightest output colour, linear 0..1 RGB. */
  light?: readonly [number, number, number];
  maxDpr?: number;
  className?: string;
}

// #region critical
const TRIANGLE = new Float32Array([-1, -1, 3, -1, -1, 3]);
const LEVELS = 5;
const CELL_SIZE = 2;
const DARK: readonly [number, number, number] = [0.035, 0.038, 0.045];
const LIGHT: readonly [number, number, number] = [0.9, 0.94, 0.92];

interface Gpu {
  gl: WebGL2RenderingContext;
  program: WebGLProgram;
  vao: WebGLVertexArrayObject;
  buffer: WebGLBuffer;
  locations: Map<string, WebGLUniformLocation | null>;
}

function build(gl: WebGL2RenderingContext): Gpu | null {
  const compile = (type: number, src: string): WebGLShader | null => {
    const shader = gl.createShader(type);
    if (!shader) return null;
    gl.shaderSource(shader, src);
    gl.compileShader(shader);
    if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
    console.error('[bayer8-ordered-dither]', gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  };

  const vert = compile(gl.VERTEX_SHADER, BAYER8_DITHER_VERT);
  const frag = compile(gl.FRAGMENT_SHADER, BAYER8_DITHER_FRAG);
  const program = gl.createProgram();
  const vao = gl.createVertexArray();
  const buffer = gl.createBuffer();
  if (!vert || !frag || !program || !vao || !buffer) return null;

  gl.attachShader(program, vert);
  gl.attachShader(program, frag);
  gl.linkProgram(program);
  gl.deleteShader(vert);
  gl.deleteShader(frag);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.error('[bayer8-ordered-dither]', gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }

  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, TRIANGLE, gl.STATIC_DRAW);
  const attrib = gl.getAttribLocation(program, 'a_pos');
  if (attrib >= 0) {
    gl.enableVertexAttribArray(attrib);
    gl.vertexAttribPointer(attrib, 2, gl.FLOAT, false, 0, 0);
  }
  gl.bindVertexArray(null);

  return { gl, program, vao, buffer, locations: new Map() };
}

function loc(gpu: Gpu, name: string): WebGLUniformLocation | null {
  const cached = gpu.locations.get(name);
  if (cached !== undefined) return cached;
  const found = gpu.gl.getUniformLocation(gpu.program, name);
  gpu.locations.set(name, found);
  return found;
}

export function Bayer8OrderedDither({
  levels = LEVELS,
  cellSize = CELL_SIZE,
  speed = 1,
  dark = DARK,
  light = LIGHT,
  maxDpr = 2,
  className,
}: Bayer8OrderedDitherProps) {
  const host = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gpuRef = useRef<Gpu | null>(null);
  const dprRef = useRef(1);

  const { width, height } = useResizeObserver(host);
  const reduced = useReducedMotion();
  const visible = useVisibility();
  const pointer = useSmoothPointer({ target: host, smoothing: 0.004 });
  const [supported, setSupported] = useState(true);

  const paramsRef = useRef({ levels, cellSize, speed, dark, light });
  paramsRef.current = { levels, cellSize, speed, dark, light };

  const drawRef = useRef<(elapsed: number) => void>(() => {});
  drawRef.current = (elapsed: number) => {
    const gpu = gpuRef.current;
    if (!gpu) return;
    const { gl } = gpu;
    const params = paramsRef.current;
    const p = pointer.current;

    gl.useProgram(gpu.program);
    gl.uniform2f(loc(gpu, 'u_resolution'), gl.drawingBufferWidth, gl.drawingBufferHeight);
    gl.uniform1f(loc(gpu, 'u_time'), elapsed * params.speed);
    gl.uniform2f(loc(gpu, 'u_pointer'), p.nx, 1 - p.ny);
    gl.uniform1f(loc(gpu, 'u_levels'), Math.max(2, Math.round(params.levels)));
    // Cell size is authored in CSS pixels and converted here, so the dither
    // grain is the same physical size on a 1x monitor and a 3x phone.
    gl.uniform1f(loc(gpu, 'u_cell'), Math.max(1, params.cellSize * dprRef.current));
    gl.uniform3f(loc(gpu, 'u_dark'), params.dark[0], params.dark[1], params.dark[2]);
    gl.uniform3f(loc(gpu, 'u_light'), params.light[0], params.light[1], params.light[2]);

    gl.bindVertexArray(gpu.vao);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.bindVertexArray(null);
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    if (!hasWebGL()) {
      setSupported(false);
      return;
    }

    const gl = canvas.getContext('webgl2', {
      antialias: false,
      alpha: false,
      depth: false,
      stencil: false,
      powerPreference: 'high-performance',
    });
    if (!gl) {
      setSupported(false);
      return;
    }

    const gpu = build(gl);
    if (!gpu) {
      loseContext(gl);
      setSupported(false);
      return;
    }
    gpuRef.current = gpu;
    setSupported(true);

    return () => {
      gpuRef.current = null;
      gl.deleteVertexArray(gpu.vao);
      gl.deleteBuffer(gpu.buffer);
      gl.deleteProgram(gpu.program);
      loseContext(gl);
    };
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    const gpu = gpuRef.current;
    if (!canvas || !gpu || width === 0 || height === 0) return;

    const dpr = pixelRatio(maxDpr);
    dprRef.current = dpr;
    const w = Math.max(1, Math.round(width * dpr));
    const h = Math.max(1, Math.round(height * dpr));
    if (canvas.width !== w || canvas.height !== h) {
      canvas.width = w;
      canvas.height = h;
    }
    gpu.gl.viewport(0, 0, w, h);
    drawRef.current(0);
  }, [width, height, maxDpr, supported, reduced]);

  const running = supported && visible && !reduced && width > 0 && height > 0;
  useRaf((_dt, elapsed) => drawRef.current(elapsed), running);
  // #endregion critical

  return (
    <div ref={host} className={cn('relative h-full w-full overflow-hidden', className)}>
      {supported ? (
        <canvas ref={canvasRef} className="block h-full w-full" />
      ) : (
        <div
          aria-hidden
          className="h-full w-full bg-bg"
          style={{
            backgroundImage:
              'radial-gradient(circle at 1px 1px, var(--k-line-strong) 1px, transparent 0), linear-gradient(180deg, var(--k-surface), var(--k-bg))',
            backgroundSize: '4px 4px, 100% 100%',
          }}
        />
      )}
    </div>
  );
}

/* ==========================================================================
   Bit-Math Bayer8 Dither — GLSL ES 3.00
   --------------------------------------------------------------------------
   The 8x8 ordered-dither matrix is DERIVED from the coordinate with six
   integer operations. No texture, no 64-entry constant array, no branches.

   Derivation. The Bayer matrix is defined recursively:

     M2   = [[0, 2], [3, 1]]
     M2n(x, y) = 4 * Mn(x mod n, y mod n) + M2(x div n, y div n)

   Write M2 in binary — 0=00, 2=10, 3=11, 1=01 — and a pattern appears:

     M2(a, b) = 2 * (a ^ b) + b

   Unrolling the recursion three times for the 8x8 case gives

     M8(x, y) = 16 * M2(x0, y0) + 4 * M2(x1, y1) + M2(x2, y2)

   where xN is bit N of x. Substituting the closed form for M2:

     M8(x, y) = 32*(x0^y0) + 16*y0
              +  8*(x1^y1) +  4*y1
              +  2*(x2^y2) +     y2

   Read as bits, that is the three-bit values of (x ^ y) and y interleaved and
   REVERSED — the least significant bit of the coordinate controls the most
   significant bit of the threshold, which is exactly what makes the pattern
   maximally dispersed rather than clustered.
   ========================================================================== */

export const BAYER8_DITHER_VERT = `#version 300 es
in vec2 a_pos;
out vec2 v_uv;

void main() {
  v_uv = a_pos * 0.5 + 0.5;
  gl_Position = vec4(a_pos, 0.0, 1.0);
}
`;

export const BAYER8_DITHER_FRAG = `#version 300 es
precision highp float;

in vec2 v_uv;
out vec4 fragColor;

uniform vec2  u_resolution;
uniform float u_time;
uniform vec2  u_pointer;
uniform float u_levels;   /* output steps per channel, including both ends */
uniform float u_cell;     /* device pixels per dither cell */
uniform vec3  u_dark;
uniform vec3  u_light;

/* Threshold in [0, 1) for this cell. See the derivation at the top of the
   file. '& 7' is the modulo — the matrix tiles every 8 cells on both axes. */
float bayer8(vec2 cellCoord) {
  ivec2 c = ivec2(floor(cellCoord));
  int x = c.x & 7;
  int y = c.y & 7;

  int v = 32 * ((x & 1) ^ (y & 1))
        + 16 * (y & 1)
        +  8 * (((x >> 1) & 1) ^ ((y >> 1) & 1))
        +  4 * ((y >> 1) & 1)
        +  2 * (((x >> 2) & 1) ^ ((y >> 2) & 1))
        +       ((y >> 2) & 1);

  /* Divide by 64, not 63. The matrix holds 0..63, and dividing by 63 would
     make the top cell land on exactly 1.0, which pushes that one cell in every
     tile a full step brighter and stamps a visible dot grid into flat areas. */
  return float(v) / 64.0;
}

/* Quantise to 'levels' evenly spaced values, offsetting by the cell threshold
   first. '(t - 0.5) / steps' centres the perturbation on zero and scales it to
   exactly one output step: any larger and the dither injects contrast of its
   own, any smaller and the bands survive. */
vec3 quantise(vec3 c, float threshold, float levels) {
  float steps = max(levels - 1.0, 1.0);
  vec3 shifted = clamp(c + (threshold - 0.5) / steps, 0.0, 1.0);
  return floor(shifted * steps + 0.5) / steps;
}

void main() {
  float aspect = u_resolution.x / max(u_resolution.y, 1.0);
  vec2 p = v_uv;
  p.x *= aspect;
  vec2 m = u_pointer;
  m.x *= aspect;

  /* A deliberately smooth, banding-prone field: a wide radial falloff around
     the pointer, a vertical ramp, and a slow horizontal sweep. Every one of
     these is the kind of gradient that shows 8-bit staircase edges. */
  float g = 1.0 - smoothstep(0.0, 1.15, distance(p, m));
  g = mix(g, 1.0 - v_uv.y, 0.42);
  g += 0.09 * sin(v_uv.x * 3.1 + u_time * 0.25);
  g = clamp(g, 0.0, 1.0);

  /* Gamma before quantisation. The level steps are evenly spaced in the
     encoded value, and the eye is not, so quantising the linear value alone
     puts all the visible banding in the shadows. */
  g = pow(g, 1.35);

  vec3 col = mix(u_dark, u_light, g);

  /* Dividing gl_FragCoord by the cell size is what decouples the dither
     pattern from the pixel grid, so the texture stays the same physical size
     on a 1x and a 3x display. */
  float threshold = bayer8(gl_FragCoord.xy / max(u_cell, 1.0));

  fragColor = vec4(quantise(col, threshold, u_levels), 1.0);
}
`;
